declare(strict_types=1);

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;

/**
 * Add only the DAV comments and system-tag surfaces to the existing NC34/35 fixtures, using the verbatim,
 * hash-checked source pins. Usage: php tests/fixtures/nextcloud-api/generate-dav-metadata.php <34|35> [output dir].
 * No network, source execution, server, SQL or unrelated fixture regeneration is involved.
 */
require __DIR__ . '/../../../vendor/autoload.php';
$major = $argv[1] ?? '';
$pins = json_decode((string)file_get_contents(__DIR__ . '/../dav-metadata-native/sources.json'), true, 512, JSON_THROW_ON_ERROR)['versions'];
if (!isset($pins[$major])) throw new RuntimeException('Expected a DAV metadata source pin: 34 or 35.');
$target = ($argv[2] ?? __DIR__) . '/' . $major . '.php';
$tree = sys_get_temp_dir() . '/mcp-dav-metadata-api-' . bin2hex(random_bytes(6));
mkdir($tree, recursive: true);
try {
	foreach ($pins[$major] as $file => $pin) {
		$source = __DIR__ . '/../dav-metadata-native/' . $major . '/' . $file;
		if (hash_file('sha256', $source) !== $pin['sha256']) throw new RuntimeException('DAV metadata source SHA256 mismatch: ' . $file);
		if (!is_dir(dirname($tree . '/' . $file))) mkdir(dirname($tree . '/' . $file), recursive: true);
		copy($source, $tree . '/' . $file);
	}
	$fixture = require $target;
	$parser = new SourceParser($tree);
	foreach (['OCA\\DAV\\Comments\\CommentsPlugin', 'OCA\\DAV\\SystemTag\\SystemTagPlugin', 'OCP\\Comments\\ICommentsManager'] as $class) {
		$surface = $parser->surface($class);
		if ($surface === null) throw new RuntimeException('Missing pinned DAV metadata surface: ' . $class);
		$fixture['classes'][$class] = $surface;
	}
	ksort($fixture['classes']);
	$original = (string)file_get_contents($target);
	$header = substr($original, 0, (int)strpos($original, 'return ['));
	$header = (string)preg_replace('~// DAV metadata surfaces generated[^\n]*\n~', '', $header);
	$header .= "// DAV metadata surfaces generated by generate-dav-metadata.php; exact source URLs and SHAs in dav-metadata-native/sources.json.\n";
	FixtureFile::write($target, $header, $fixture);
	echo 'Generated three DAV metadata surfaces for NC' . $major . "\n";
} finally {
	$files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($tree, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
	foreach ($files as $file) $file->isDir() ? rmdir($file->getPathname()) : unlink($file->getPathname());
	rmdir($tree);
}
